import Foundation
struct SSHOptions:Codable,Equatable {
 var jumpHost="";var connectTimeout=30;var keepAliveInterval=30;var keepAliveCount=3;var compression=false
 func validated()throws->SSHOptions{guard (1...600).contains(connectTimeout),(0...3600).contains(keepAliveInterval),(1...100).contains(keepAliveCount) else{throw SFTPError.message("连接超时应为 1–600 秒；保活间隔 0–3600 秒；失败次数 1–100")};if !jumpHost.isEmpty{let regex=try NSRegularExpression(pattern:"^(?:[A-Za-z0-9_.-]+@)?(?:[A-Za-z0-9_][A-Za-z0-9_.-]*|\\[[0-9A-Fa-f:]+\\])(?::[0-9]{1,5})?$");for hop in jumpHost.split(separator:",",omittingEmptySubsequences:false){let text=String(hop);guard regex.firstMatch(in:text,range:NSRange(text.startIndex...,in:text)) != nil else{throw SFTPError.message("跳板机格式应为 user@host:port，可用逗号连接多级跳板；不接受命令或空格")};if let last=text.split(separator:"]").last,text.contains("]:"){guard let port=Int(last.dropFirst()),(1...65535).contains(port) else{throw SFTPError.message("跳板机端口无效")}}else if !text.contains("["),let tail=text.split(separator:":").last,text.contains(":"),let port=Int(tail),!(1...65535).contains(port){throw SFTPError.message("跳板机端口无效")}}};return self}
 var arguments:[String]{var args=["-o","ConnectTimeout=\(connectTimeout)","-o","ServerAliveInterval=\(keepAliveInterval)","-o","ServerAliveCountMax=\(keepAliveCount)","-o","Compression=\(compression ? "yes" : "no")"];if !jumpHost.isEmpty{args += ["-J",jumpHost]};return args}
}
enum SSHArguments {
 static func master(_ session:Session,socket:String)throws->[String]{let s=try session.validated();guard s.fileProtocol == .sftp else{throw SFTPError.message("此协议不提供 SSH 通道")};var args=["-M","-S",socket,"-o","ControlPersist=no"]+s.sshOptions.arguments+["-p",String(s.port)];if !s.user.isEmpty{args += ["-l",s.user]};if !s.key.isEmpty{args += ["-i",(s.key as NSString).expandingTildeInPath]};return args+["-N",s.host]}
 static func terminal(_ session:Session,socket:String,directory:String)throws->[String]{var args=try sftp(session,socket:socket);args.removeLast(3);return args+["-t",session.host,try ShellPath.terminalCommand(directory:directory)]}
 static func sftp(_ session:Session,socket:String)throws->[String]{let s=try session.validated();guard s.fileProtocol == .sftp else{throw SFTPError.message("此协议不提供 SSH 通道")};var args=["-S",socket,"-o","BatchMode=yes","-o","ProxyCommand=/usr/bin/false","-o","ConnectTimeout=\(s.sshOptions.connectTimeout)","-p",String(s.port)];if !s.user.isEmpty{args += ["-l",s.user]};return args+["-s",s.host,"sftp"]}
}
